import from models.Project { Project, create_root_project, get_project }
import from models.Task { Task }

walker Visitor {
    can start with Root entry {
        print("Root");
        visit [-->];
    }
    can check_project with Project entry {
        print(f">> Visit >> (Project) {here.get_name()}");
        visit [-->];
    }
    can check_task with Task entry {
        print(f">> Visit >> (Task) {here.get_alias()}");
        visit [-->];
    }
}

walker Cleaner {
    can with Root entry {
        visit [-->];
    }
    can del_project with Project entry {
        visit [-->];
        print(f"[Delete] (Project) {here.get_name()}");
        del here;
    }
    can del_task with Task entry {
        visit [-->];
        print(f"[Delete] (Task) {here.get_alias()}");
        del here;
    }
}

walker FindTask {
    has task_id: str;
    has found: Task | None = None;

    can search with Project entry {
        for t in [-->][?:Task] {
            if jid(t) == self.task_id {
                self.found = t;
            }
        }
    }
}

walker Approver {
    can with Root entry {
        visit [-->];
    }
    can approve_project with Project entry {
        here.is_draft = False;
        visit [-->];
    }
    can approve_task with Task entry {
        here.is_draft = False;
        visit [-->];
    }
}

def:pub delete_project(id: str) -> bool {
    p = get_project(id);
    if p is None {
        return False;
    }
    p spawn Cleaner();
    return True;
}

def:pub delete_task(project_id: str, task_id: str) -> bool {
    p = get_project(project_id);
    if p is None {
        return False;
    }
    result = p spawn FindTask(task_id=task_id);
    if result.found is None {
        return False;
    }
    result.found spawn Cleaner();
    return True;
}

def:pub approve_project(id: str) -> bool {
    p = get_project(id);
    if p is None {
        return False;
    }
    p spawn Approver();
    return True;
}

def:pub approve_task(project_id: str, task_id: str) -> bool {
    p = get_project(project_id);
    if p is None {
        return False;
    }
    result = p spawn FindTask(task_id=task_id);
    if result.found is None {
        return False;
    }
    result.found spawn Approver();
    return True;
}

