            part = await reader.read();
            if part.done {
                feeding = False;
            } else {
                buf = buf + decoder.decode(part.value, {"stream": True});
                frames = buf.split(sep);
                buf = frames.pop();
                for frame in frames {
                    for line in frame.split(nl) {
                        if line.startswith("data: ") and not frame.startswith("event:") {
                            # Each data frame is a JSON-encoded str chunk from
                            # guestbook_story; str() pins the type for the checker.
                            acc = acc + str(JSON.parse(line[6:]));
                            story = acc;
                        }
                    }
                }
            }
        }
    } except Exception as e {
        story = acc + " [stream interrupted]";
    }
    storyOn = False;
}

impl Showcase.loadSource -> None {
    srcFiles = await list_source_files();
    srcLoading = True;
    srcFile = await get_source_file("frontend.jac");
    srcLoading = False;
}

impl Showcase.openSource(path: str) -> None {
    srcLoading = True;
    srcFile = await get_source_file(path);
    srcLoading = False;
}
