import from .store { TrajectoryNode, SubagentRef }

def:pub findNode(treeRoot: TrajectoryNode, nodeId: str) -> TrajectoryNode | None {
    if treeRoot.id == nodeId {
        return treeRoot;
    }
    for c in treeRoot.children {
        found = findNode(c, nodeId);
        if found is not None {
            return found;
        }
    }
    return None;
}

def:pub subagentRefFor(nodeId: str, subagentByNodeId: dict) -> SubagentRef | None {
    return subagentByNodeId[nodeId] if nodeId in subagentByNodeId else None;
}
