def _renderBody(targetNode: TrajectoryNode, parsed: any) -> JsxElement {
    if targetNode.kind == "user_message" or targetNode.kind == "assistant_text" {
        text = parsed["text"] if parsed and parsed["text"] else targetNode.summary;
        return <pre className="whitespace-pre-wrap text-sm">{text}</pre>;
    }
    if targetNode.kind == "thinking" {
        text = parsed["thinking"] if parsed and parsed["thinking"] else "";
        if len(text) == 0 {
            return <p className="text-sm italic text-muted-foreground">
                (Reasoning text not stored in the log - only an encrypted verification signature is kept on disk.)
            </p>;
        }
        return <pre className="whitespace-pre-wrap text-sm italic text-muted-foreground">{text}</pre>;
    }
    if targetNode.kind == "tool_use" {
        call = parsed["tool_use"] if parsed and parsed["tool_use"] else parsed;
        result = parsed["tool_result"] if parsed and parsed["tool_result"] else None;
        input = call["input"] if call else {};
        resultText = result["content"] if result and result["content"] else "";
        return <div className="flex flex-col gap-3">
            <div>
                <div className="mb-1 text-sm font-semibold">Input</div>
                <pre className="overflow-x-auto whitespace-pre-wrap rounded bg-muted p-3 text-xs">{JSON.stringify(input, None, 2)}</pre>
            </div>
            {result and <div>
                <div className="mb-1 text-sm font-semibold">Result</div>
                <pre className="overflow-x-auto whitespace-pre-wrap rounded bg-muted p-3 text-xs">{resultText}</pre>
            </div>}
        </div>;
    }
    if targetNode.kind == "tool_result" {
        text = parsed["content"] if parsed and parsed["content"] else "";
        return <pre className="overflow-x-auto whitespace-pre-wrap rounded bg-muted p-3 text-xs">{text}</pre>;
    }
    if targetNode.kind == "subagent_spawn" {
        call = parsed["tool_use"] if parsed and parsed["tool_use"] else parsed;
        prompt = "(no prompt captured)";
        if call and call["input"] and call["input"]["prompt"] {
            prompt = call["input"]["prompt"];
        }
        return <div className="flex flex-col gap-3">
            <div>
                <div className="mb-1 text-sm font-semibold">Instruction given to subagent</div>
                <pre className="overflow-x-auto whitespace-pre-wrap rounded bg-muted p-3 text-xs">{prompt}</pre>
            </div>
        </div>;
    }
    return <pre className="overflow-x-auto whitespace-pre-wrap rounded bg-muted p-3 text-xs">{JSON.stringify(parsed, None, 2)}</pre>;
}

def:pub NodeDetailModal(
    targetNode: TrajectoryNode | None,
    open: bool,
    onOpenChange: Callable[[bool], None],
    subagentByNodeId: dict,
    onOpenSubagent: Callable[[SubagentRef], None],
) -> JsxElement {
    def handle_open_change(next: bool) {
        onOpenChange(next);
    }

    parsed: any = None;
    subagentRef: SubagentRef | None = None;
    if targetNode is not None {
        try {
            parsed = JSON.parse(targetNode.raw_json);
        } except Exception {
            parsed = None;
        }
        subagentRef = subagentRefFor(targetNode.id, subagentByNodeId);
    }

    def handle_view_subagent(e: MouseEvent) {
        if subagentRef {
            onOpenSubagent(subagentRef);
        }
    }

    <Dialog open={open} onOpenChange={handle_open_change}>
        <DialogContent className="max-h-[80vh] max-w-2xl overflow-y-auto">
            {targetNode and <DialogHeader>
                <DialogTitle className="flex items-center gap-2">
                    <Badge style={{"backgroundColor": kindColor(targetNode.kind), "color": "white"}}>{kindLabel(targetNode.kind)}</Badge>
                    {targetNode.tool_name and <span>{targetNode.tool_name}</span>}
                </DialogTitle>
                <DialogDescription>{targetNode.timestamp}</DialogDescription>
            </DialogHeader>}

            {targetNode and _renderBody(targetNode, parsed)}

            {subagentRef and <Button onClick={handle_view_subagent}>View subagent trajectory →</Button>}
        </DialogContent>
    </Dialog>
}
