import from "@jac/runtime" { useNavigate }
import from "..components.ui.card" { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter }
import from "..components.ui.button" { Button }
import from "..components.ui.toggle" { Toggle }

def:pub HomeShell() -> JsxElement {
    has username: str = "";
    has advancedPath: str = "";
    has advanced: bool = False;

    nav = useNavigate();

    def handle_username_change(e: ChangeEvent) {
        username = e.target.value;
    }

    def handle_advanced_path_change(e: ChangeEvent) {
        advancedPath = e.target.value;
    }

    def handle_toggle_advanced(pressed: bool) {
        advanced = pressed;
    }

    def handle_submit(e: FormEvent) {
        e.preventDefault();
        claudeRoot = advancedPath if advanced and len(advancedPath) > 0 else ("/home/" + username + "/.claude");
        nav("/projects?claudeRoot=" + encodeURIComponent(claudeRoot));
    }

    <div className="flex min-h-screen items-center justify-center bg-background p-6 text-foreground">
        <Card className="w-full max-w-md">
            <CardHeader>
                <CardTitle>ClaudeLogViewer</CardTitle>
                <CardDescription>Pick whose Claude Code trajectory logs to browse.</CardDescription>
            </CardHeader>
            <form onSubmit={handle_submit}>
                <CardContent className="flex flex-col gap-4">
                    {not advanced and <div className="flex flex-col gap-1.5">
                        <label className="text-sm font-medium" htmlFor="username">Username</label>
                        <input
                            id="username"
                            className="rounded-md border bg-background px-3 py-2 text-sm"
                            placeholder="e.g. imrui"
                            value={username}
                            onChange={handle_username_change}
                        />
                        <p className="text-xs text-muted-foreground">Resolves to /home/{username or "<username>"}/.claude</p>
                    </div>}

                    {advanced and <div className="flex flex-col gap-1.5">
                        <label className="text-sm font-medium" htmlFor="advancedPath">Full path to .claude</label>
                        <input
                            id="advancedPath"
                            className="rounded-md border bg-background px-3 py-2 text-sm"
                            placeholder="/home/someone/.claude"
                            value={advancedPath}
                            onChange={handle_advanced_path_change}
                        />
                    </div>}

                    <Toggle pressed={advanced} onPressedChange={handle_toggle_advanced} className="self-start">
                        Advanced: enter full path
                    </Toggle>
                </CardContent>
                <CardFooter>
                    <Button type="submit" className="w-full">Browse projects</Button>
                </CardFooter>
            </form>
        </Card>
    </div>
}
