import from "reactflow" { ReactFlow, Background, Controls }
import "reactflow/dist/style.css";
import from .TrajGraphNode { TrajGraphNode }
import from .store { TrajectoryNode }

glob _nodeTypes: dict = {"trajNode": TrajGraphNode};

def:pub buildGraphElements(treeRoot: TrajectoryNode, showSystem: bool) -> dict {
    flowNodes: list[dict] = [];
    flowEdges: list[dict] = [];
    leafX: int = 0;

    def layoutNode(treeNode: TrajectoryNode, depth: int, parentId: str | None) -> float {
        visibleChildren: list[TrajectoryNode] = [
            c for c in treeNode.children if showSystem or c.kind != "system_event"
        ];

        centerX: float = 0.0;
        if len(visibleChildren) == 0 {
            centerX = leafX as float;
            leafX = leafX + 1;
        } else {
            total: float = 0.0;
            for c in visibleChildren {
                total = total + layoutNode(c, depth + 1, treeNode.id);
            }
            centerX = total / len(visibleChildren);
        }

        flowNodes.append({
            "id": treeNode.id,
            "type": "trajNode",
            "position": {"x": centerX * 230.0, "y": (depth as float) * 150.0},
            "data": {
                "kind": treeNode.kind,
                "summary": treeNode.summary,
                "toolName": treeNode.tool_name,
                "isSidechain": treeNode.is_sidechain,
            },
        });
        if parentId is not None {
            flowEdges.append({
                "id": f"e-{parentId}-{treeNode.id}",
                "source": parentId,
                "target": treeNode.id,
            });
        }
        return centerX;
    }

    # Always lay out the root itself - hiding it entirely (even when it's a
    # synthetic wrapper / system_event) would blank the whole graph, which
    # is worse than just showing one gray "Event" node.
    layoutNode(treeRoot, 0, None);

    return {"nodes": flowNodes, "edges": flowEdges};
}

def:pub TrajectoryGraph(treeRoot: TrajectoryNode, showSystem: bool, onSelectNode: Callable[[str], None]) -> JsxElement {
    elements = buildGraphElements(treeRoot, showSystem);

    def handle_node_click(event: Event, flowNode: dict) {
        onSelectNode(flowNode["id"]);
    }

    <div className="h-full w-full">
        <ReactFlow
            key={treeRoot.id + str(showSystem)}
            nodes={elements["nodes"]}
            edges={elements["edges"]}
            nodeTypes={_nodeTypes}
            onNodeClick={handle_node_click}
            fitView={True}
            minZoom={0.1}
        >
            <Background />
            <Controls />
        </ReactFlow>
    </div>
}
