import from "@jac/runtime" { useNavigate, Link }
import from .store { list_sessions, SessionSummary }
import from .SessionCard { SessionCard }
import from "..components.ui.skeleton" { Skeleton }

def:pub SessionListShell(projectDir: str) -> JsxElement {
    has sessions: list[SessionSummary] = [];
    has loading: bool = True;
    has loadError: str = "";

    nav = useNavigate();

    async can with [projectDir] entry {
        loading = True;
        loadError = "";
        try {
            sessions = await list_sessions(projectDir);
        } except Exception as e {
            loadError = str(e);
        }
        loading = False;
    }

    def handle_open(session: SessionSummary) {
        nav("/trajectory?file=" + encodeURIComponent(session.file_path));
    }

    <div className="mx-auto max-w-4xl p-6">
        <Link to="/" className="text-sm text-muted-foreground hover:underline">← Home</Link>
        <h1 className="mb-1 mt-2 text-2xl font-semibold">Sessions</h1>
        <p className="mb-6 text-sm text-muted-foreground">{projectDir}</p>

        {loading and <div className="flex flex-col gap-3">
            <Skeleton className="h-20 w-full" />
            <Skeleton className="h-20 w-full" />
        </div>}

        {(not loading and len(loadError) > 0) and <div className="text-sm text-destructive">
            Could not load sessions: {loadError}
        </div>}

        {(not loading and len(loadError) == 0 and len(sessions) == 0) and <div className="text-sm text-muted-foreground">
            No sessions found in this project.
        </div>}

        {(not loading and len(loadError) == 0) and <div className="flex flex-col gap-3">
            {for s in sessions {
                <SessionCard key={s.session_id} session={s} onOpen={handle_open} />
            }}
        </div>}
    </div>
}
