import from "@jac/runtime" { useNavigate }
import from .store { list_projects, ProjectSummary }
import from .ProjectCard { ProjectCard }
import from "..components.ui.skeleton" { Skeleton }

def:pub ProjectListShell(claudeRoot: str) -> JsxElement {
    has projects: list[ProjectSummary] = [];
    has loading: bool = True;
    has loadError: str = "";

    nav = useNavigate();

    async can with [claudeRoot] entry {
        loading = True;
        loadError = "";
        try {
            projects = await list_projects(claudeRoot);
        } except Exception as e {
            loadError = str(e);
        }
        loading = False;
    }

    def handle_open(project: ProjectSummary) {
        nav("/sessions?projectDir=" + encodeURIComponent(claudeRoot + "/projects/" + project.dir_name));
    }

    <div className="mx-auto max-w-4xl p-6">
        <h1 className="mb-1 text-2xl font-semibold">Projects</h1>
        <p className="mb-6 text-sm text-muted-foreground">{claudeRoot}</p>

        {loading and <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <Skeleton className="h-28 w-full" />
            <Skeleton className="h-28 w-full" />
        </div>}

        {(not loading and len(loadError) > 0) and <div className="text-sm text-destructive">
            Could not load projects: {loadError}
        </div>}

        {(not loading and len(loadError) == 0 and len(projects) == 0) and <div className="text-sm text-muted-foreground">
            No projects found under this .claude folder.
        </div>}

        {(not loading and len(loadError) == 0) and <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            {for p in projects {
                <ProjectCard key={p.dir_name} project={p} onOpen={handle_open} />
            }}
        </div>}
    </div>
}
